测试结果明确了：Firecrawl search 超时，但 scrape 可以抓官网。现在设计整合方案。 **架构设计：代码01 同时调用两个 MCP 端点** ```mermaid graph LR A[大模型01 提取region] --> B[代码01 Python] B -->|urllib| C[博查 MCP<br/>中文新闻] B -->|urllib| D[Firecrawl MCP<br/>官网产品页] C --> E[合并生成报告] D --> E E --> F[End] ``` **数据分工：** - 博查 → 中文行业新闻（海尔/海信/三星海外动态） - Firecrawl → 竞品官网产品列表（型号/价格/规格） 把代码01 替换为以下 Python 代码： ```python import json import urllib.request import re from datetime import datetime, timezone, timedelta def handler(inputs): raw = json.loads(inputs) if isinstance(inputs, str) else inputs region = raw.get("region", "欧洲") if isinstance(raw.get("input"), str): try: inner = json.loads(raw["input"]) region = inner.get("region", region) except: pass KEY = "pk_b1fb70c791093782097c3405bb9854cd18cccfe520714fa89932b20f8239f625" BOCHA = "https://market.haierfhtech.com/prod-api/capabilitymarket/mcp/http/cap_66abf82820f1468dbf60175c3f529670" FC = "https://market.haierfhtech.com/prod-api/capabilitymarket/mcp/http/cap_719957985ee345948726696a4cb59f7c" def mcp_call(url, tool, args): body = json.dumps({ "jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": tool, "arguments": args} }).encode() req = urllib.request.Request(url, data=body, method="POST") req.add_header("Content-Type", "application/json") req.add_header("X-Platform-Access-Key", KEY) try: with urllib.request.urlopen(req, timeout=20) as r: t = r.read().decode() i = t.find("{") if i >= 0: o = json.loads(t[i:]) inner = o.get("result", {}).get("content", [{}])[0].get("text", "") if inner: return json.loads(inner) except: pass return {} # === 1. 博查：中文行业新闻 === qs = { "欧洲": "三星 LG 博世 海尔 冰箱 欧洲 2026 新品 市场", "澳洲": "海信 美的 三星 LG 西屋 冰箱 澳洲 2026", "美洲": "三星 LG 惠而浦 海尔 海信 冰箱 美国 2026", "独联体": "海尔 海信 三星 LG 冰箱 俄罗斯 2026", "东南亚": "三星 LG 松下 海尔 美的 冰箱 东南亚 2026", "南亚": "三星 LG 海尔 冰箱 印度 2026", "中东非": "海尔 海信 三星 LG 冰箱 中东 非洲 2026", "东亚": "三星 LG 松下 日立 海尔 冰箱 日本 韩国 2026" } news = mcp_call(BOCHA, "web_search", { "query": qs.get(region, qs["欧洲"]), "count": 6, "freshness": "pastMonth" }) pages = news.get("data", {}).get("webPages", {}).get("value", []) # === 2. Firecrawl：抓取竞品官网产品列表 === fc_urls = { "欧洲": ("https://www.samsung.com/uk/refrigerators/all-refrigerators/", "Samsung UK"), "美洲": ("https://www.samsung.com/us/refrigerators/all-refrigerators/", "Samsung US"), "澳洲": ("https://hisense.com.au/appliances/fridges-freezers/all?sortCode=newestArrival-desc&currentPage=0", "Hisense AU"), "东南亚": ("https://www.samsung.com/sg/refrigerators/all-refrigerators/", "Samsung SG"), "南亚": ("https://www.samsung.com/in/refrigerators/all-refrigerators/", "Samsung IN"), "中东非": ("https://www.lg.com/africa/refrigerators", "LG Africa"), "东亚": ("https://www.samsung.com/jp/refrigerators/", "Samsung JP"), "独联体": ("https://www.samsung.com/ru/refrigerators/all-refrigerators/", "Samsung RU"), } url, label = fc_urls.get(region, fc_urls["欧洲"]) fc = mcp_call(FC, "firecrawl_scrape", { "url": url, "formats": ["markdown"], "onlyMainContent": True }) raw_md = fc.get("data", {}).get("markdown", "") # 从海量 markdown 中提取产品名和价格 products = [] if raw_md: # 提取产品名称（大写字母开头、含关键词的行） names = re.findall( r'(?:Bespoke[^
]{10,80}|French\s*Door[^
