ng UK"), "美洲": ("https://www.samsung.com/us/refrigerators/all-refrigerators/", "Samsung US"), "澳洲": ("https://hisense.com.au/appliances/fridges-freezers/all?sortCode=newestArrival-desc&currentPage=0", "Hisense AU"), "东南亚": ("https://www.samsung.com/sg/refrigerators/all-refrigerators/", "Samsung SG"), "南亚": ("https://www.samsung.com/in/refrigerators/all-refrigerators/", "Samsung IN"), "中东非": ("https://www.lg.com/africa/refrigerators", "LG Africa"), "东亚": ("https://www.samsung.com/jp/refrigerators/", "Samsung JP"), "独联体": ("https://www.samsung.com/ru/refrigerators/all-refrigerators/", "Samsung RU"), } url, label = fc_urls.get(region, fc_urls["欧洲"]) fc = mcp_call(FC, "firecrawl_scrape", { "url": url, "formats": ["markdown"], "onlyMainContent": True }) # 🔧 Firecrawl 返回 {"markdown": "...", "metadata": {...}}，不是 {"data": {...}} raw_md = fc.get("markdown", "") products = [] prices = [] if raw_md: # 提取产品名称 names = re.findall( r'(?:Bespoke[^
